  private TreasureShape TreasurePicture(Transform parent,string name,Vector2 at,Vector2 size,string kind){var shape=Rect(parent,name,at,size).gameObject.AddComponent<TreasureShape>();shape.kind=kind;shape.raycastTarget=false;return shape;}
  private void ChooseTreasure(){CloseMiniGames();CloseNavigation();Narration.Stop();SendTreasure("start");}
  private void SendTreasure(string op,string target=""){
   if(!Ready || TravelPending || treasureSending && op!="leave")return;treasureSending=true;treasureApproach="";destination=null;CancelPointers();manualCamera=false;shared?.Walk(WalkMode.Stop);
   void Done(SoloResult r){treasureSending=false;if(!r.Accepted){homeFeedback.text=r.Outcome=="match-map-pictures"?"Match the chest pictures to map pieces 1, 2 and 3.":"Follow our current clue. Tap Show me for a hand.";homeFeedbackUntil=Time.unscaledTime+4;}else if(op=="lift" || op=="dig"){if(TreasureGame.lastFind>0)Narration.Speak("treasure-surprise");}else if(op=="note"){if(TreasureGame.tuneStep==0)Narration.Speak("treasure-retry");else if(int.TryParse(target,out var n) && treasureNotes[n]!=null)treasureTone.PlayOneShot(treasureNotes[n]);}Render();}
   if(Shared){if(!SubmitShared(SoloAction.Treasure,"",target,op,0,0,Done))treasureSending=false;}else Done(Command(SoloAction.Treasure,target:target,value:op));
  }
  private void RequestTreasure(string target,string op){if(!Ready || MenuOpen || !TreasureOwn)return;CancelPointers();treasureApproach=target;treasureOperation=op;manualCamera=false;var at=op=="wheel"?TreasureHunt.Dig(TreasureGame.site):TreasureHunt.Point(TreasureGame,target);destination=new Vector2(at.X,at.Y);}
  private void CheckTreasureInput(){
   if(treasureApproach=="")return;if(CurrentArea!=TreasureHunt.Zone || !TreasureOwn || MenuOpen || applicationPaused || stickDirection.sqrMagnitude>.1f){treasureApproach="";destination=null;return;}
   if(treasureSending || ActionPending)return;var at=treasureOperation=="wheel"?TreasureHunt.Dig(TreasureGame.site):TreasureHunt.Point(TreasureGame,treasureApproach);var p=ReadPlayer(Actor);if(Math.Abs(p.x-at.X)>15 || Math.Abs(p.y-at.Y)>25)return;
   if(treasureOperation=="visit"){treasureApproach="";destination=null;shared?.Walk(WalkMode.Stop);return;}SendTreasure(treasureOperation,treasureApproach);
  }
  private void TreasureHelp(){var g=TreasureGame;if(g==null || g.phase<2)return;treasureMystery=false;RequestTreasure(TreasureHunt.Next(g),"visit");SpeakTreasure();}
  private void SpeakTreasure(){var g=TreasureGame;if(g==null)return;Narration.Speak("treasure-"+(g.phase==5?"site-"+g.site:treasureMystery && g.phase>=2 && g.phase<=4?"mystery-"+g.phase:"step-"+g.phase));}
  private void TreasureAction(int i){var g=TreasureGame;if(g==null)return;
   if(g.phase==2 || g.phase==3){var index=(g.phase==2?0:3)+i;var correct=index==(g.phase==2?g.shell:3+g.pot);RequestTreasure("cover-"+index,g.lifted[index] && correct?"take":"lift");}
   else if(g.phase==4)RequestTreasure(i.ToString(),"note");else if(g.phase==5)RequestTreasure("dig-"+i,"dig");else if(g.phase==6)RequestTreasure(i.ToString(),"wheel");
  }
