  private void TickTreasure(){
   if(treasureHud==null || treasureFrame==Time.frameCount)return;treasureFrame=Time.frameCount;var g=TreasureGame;var visible=CurrentArea==TreasureHunt.Zone && g!=null;
   if(g!=null)treasureClockRendered=treasurePresentationClock.Step(g.clock,"treasure/"+g.round,
    Shared && shared.Connected,Time.unscaledTimeAsDouble,Mathf.Min(Time.unscaledDeltaTime,.1f));

   var own=visible && TreasureOwn && !MenuOpen;var dt=Mathf.Min(Time.unscaledDeltaTime,.1f);
   treasureHud.gameObject.SetActive(own && g.phase!=1);treasureBelt.gameObject.SetActive(own && g.phase!=1);treasureOpening.gameObject.SetActive(own && g.phase==1);var scale=Mathf.Min(1,safe.rect.width/1060);treasureHud.localScale=treasureBelt.localScale=Vector3.one*scale;treasureOpening.localScale=Vector3.one*Mathf.Min(safe.rect.width/930,safe.rect.height/550);if(treasureOpening.gameObject.activeSelf)treasureOpening.SetAsLastSibling();
   for(var i=0;i<6;i++){var root=treasureCovers[i].rectTransform;root.gameObject.SetActive(visible);treasureFinds[i].gameObject.SetActive(false);if(!visible)continue;var at=TreasureHunt.Cover(i);var correct=i==(i<3?g.shell:3+g.pot);var lifted=g.lifted[i];root.anchoredPosition=ToBoard(at.X,at.Y)+new Vector2(lifted?65:0,lifted?66:20)*sceneScale;root.localScale=Vector3.one*sceneScale;treasureCovers[i].special=correct;treasureCovers[i].count=correct?3:i%3+1==3?2:1;treasureCovers[i].SetVerticesDirty();var find=treasureFinds[i];find.gameObject.SetActive(lifted && (!correct || (i<3?g.phase==2:g.phase==3)));find.kind=correct?"map":i<3?"crab":"boot";find.symbol=g.tune[i<3?0:1];find.rectTransform.anchoredPosition=ToBoard(at.X,at.Y)+new Vector2(0,5)*sceneScale;find.rectTransform.localScale=Vector3.one*sceneScale;find.SetVerticesDirty();}
   treasureChimes.gameObject.SetActive(visible);if(visible){treasureChimes.anchoredPosition=ToBoard(3900,360);treasureChimes.localScale=Vector3.one*sceneScale;}
   for(var i=0;i<3;i++){var root=treasureMounds[i].rectTransform;root.gameObject.SetActive(visible && !(g.phase>=6 && i==g.site));if(visible){var at=TreasureHunt.Dig(i);root.anchoredPosition=ToBoard(at.X,at.Y);root.localScale=Vector3.one*sceneScale;}}
   treasureChest.gameObject.SetActive(visible && g.phase>=6);treasureEnding.gameObject.SetActive(visible && g.phase==7);if(visible && g.phase>=6){var at=TreasureHunt.Dig(g.site);treasureChest.anchoredPosition=ToBoard(at.X,at.Y);treasureChest.localScale=Vector3.one*sceneScale;var shape=treasureChest.GetComponent<TreasureShape>();shape.open=g.phase==7;shape.SetVerticesDirty();treasureEnding.anchoredPosition=ToBoard(at.X,at.Y)+new Vector2(0,-42)*sceneScale;treasureEnding.localScale=Vector3.one*sceneScale;}
   for(var i=0;i<3;i++){var npc=treasureFriends[i];npc.root.gameObject.SetActive(visible);if(!visible)continue;npc.visual.Select(g.friends[i]);var point=TreasureHunt.Friend(g,i,treasureClockRendered);var target=new Vector2(point.X,point.Y);var frame=treasureMotion[i].Step(target,"treasure/"+g.round+"/"+i,i==1,180,dt);var p=treasureNpcPoints[i]=treasureMotion[i].Point;npc.root.anchoredPosition=ToBoard(p.x,p.y);npc.root.localScale=Vector3.one*sceneScale*.8f;var pose=frame.Speed>1?frame.Pose:g.phase==7?CharacterPose.Dance:i==2 && g.phase==4?CharacterPose.Wave:i==1?CharacterPose.Carry:CharacterPose.Idle;npc.visual.PresentNpcFrame(new CharacterFrame(pose,frame.Speed,frame.FaceLeft,(float)(g.clock-g.started),frame.Travel,frame.ResetMotion),dt,.8f);}
   treasureTeacher.gameObject.SetActive(visible);if(visible){var at=TreasureHunt.Point(g,TreasureHunt.Next(g));var target=new Vector2(Mathf.Clamp(at.X+300,300,4620),440);var teacherFrame=treasureTeacherLocomotion.Step(target,"treasure/"+g.round,false,180,dt);treasureTeacherPoint=treasureTeacherLocomotion.Point;treasureTeacher.anchoredPosition=ToBoard(treasureTeacherPoint.x,treasureTeacherPoint.y);treasureTeacher.localScale=Vector3.one*sceneScale*.8f;var pose=teacherFrame.Pose==CharacterPose.Walk?0:g.phase==7?3:1;treasureTeacherWalk.Present(teacherFrame,pose,dt,.8f);}
   treasureMap.localScale=Vector3.one*Mathf.Min(safe.rect.width/930,safe.rect.height/500);for(var i=0;i<3;i++)treasureMapMarks[i].gameObject.SetActive(g!=null && g.phase>=5 && g.site==i);if(treasureMap.gameObject.activeSelf){if(own)treasureMap.SetAsLastSibling();else treasureMap.gameObject.SetActive(false);}
   if(!own){treasureSpoken=-1;treasureApproach="";return;}
   if(treasureRound!=g.round){treasureRound=g.round;treasureMystery=false;treasureSpoken=-1;treasureDemoAt=-11;}
   treasureHint.text=treasureMystery?TreasureHunt.MysteryClue(g):TreasureHunt.PictureClue(g);treasureClue.gameObject.SetActive(!treasureMystery);treasureClue.kind=g.phase==3?"pot":g.phase==4?"chimes":g.phase==5?new[]{"palm","flowers","lookout"}[g.site]:g.phase>=6?"map":"shell";treasureClue.special=true;treasureClue.symbol=g.phase==5?g.site:0;treasureClue.SetVerticesDirty();
   var pieces=g.phase>=5?3:g.phase>=4?2:g.phase>=3?1:0;treasureProgress.text="Our map · "+pieces+" / 3 pieces";for(var i=0;i<3;i++){treasurePieces[i].gameObject.SetActive(i<pieces);treasurePieces[i].symbol=g.tune[i];treasurePieces[i].SetVerticesDirty();}
   for(var i=0;i<3;i++){var icon=treasureActionIcons[i];var label=treasureActionLabels[i];treasureActions[i].interactable=g.phase>=2 && g.phase<=6;icon.special=false;icon.count=3;
    if(g.phase==2 || g.phase==3){var index=i+(g.phase==2?0:3);var correct=index==(g.phase==2?g.shell:3+g.pot);icon.kind=g.phase==2?"shell":"pot";icon.special=correct;icon.count=correct?3:i==2?2:1;label.text=correct && g.lifted[index]?"Take map piece":"Lift "+(g.phase==2?"shell ":"pot ")+(i+1);}
    else if(g.phase==4){icon.kind="symbol";icon.symbol=i;label.text=TreasureHunt.Symbol(i)+(g.tuneStep>0 && i==g.tune[g.tuneStep-1]?" ✓":"");}
    else if(g.phase==5){icon.kind="symbol";icon.symbol=i;label.text="Dig "+TreasureHunt.Landmark(i);}
    else if(g.phase==6){icon.kind="symbol";icon.symbol=g.wheels[i];label.text="Lock "+(i+1)+": "+TreasureHunt.Symbol(g.wheels[i]);}
    else{icon.kind=new[]{"compass","symbol","boat"}[i];icon.symbol=2;label.text=new[]{"Golden compass","Sparkly stars","Little boat"}[i];}icon.SetVerticesDirty();
   }
   treasureActionLabels[3].text=g.phase==6?"Open chest":g.phase==7?"New hunt":g.phase==4?"Hear the tune":"Explore together";treasureActions[3].interactable=g.phase==4 || g.phase>=6;
   if(treasureSpoken!=g.phase){treasureSpoken=g.phase;Narration.Stop();SpeakTreasure();}
   if(g.demoAt!=treasureDemoAt){treasureDemoAt=g.demoAt;treasureDemoNote=-1;var voice=Narration.GetComponent<AudioSource>();treasureDemoStartAt=Time.unscaledTime+(voice!=null && voice.isPlaying?Mathf.Max(0,voice.clip.length-voice.time):0)+.3f;}
   var elapsed=Time.unscaledTime-treasureDemoStartAt;var note=elapsed<0?-1:(int)(elapsed/.8f);
   foreach(var icon in treasureActionIcons)icon.rectTransform.localScale=Vector3.one*.48f;var chime=treasureChimes.GetComponent<TreasureShape>();chime.pulse=g.phase==4 && note>=0 && note<3?g.tune[note]:-1;chime.SetVerticesDirty();
   if(g.phase==4 && g.demoAt>=0 && note>=0 && note<3){var icon=treasureActionIcons[g.tune[note]];icon.rectTransform.localScale=Vector3.one*.65f;if(note!=treasureDemoNote){treasureDemoNote=note;if(treasureNotes[g.tune[note]]!=null)treasureTone.PlayOneShot(treasureNotes[g.tune[note]]);}}

  }
  private void AddTreasureDepth(Action<RectTransform,float,int,string> add){foreach(var s in treasureCovers.Concat(treasureFinds).Concat(treasureMounds))if(s.gameObject.activeSelf)add(s.rectTransform,s.rectTransform.anchoredPosition.y-20*sceneScale,2,s.name);foreach(var n in treasureFriends)if(n.root.gameObject.activeSelf)add(n.root,n.root.anchoredPosition.y,3,n.root.name);if(treasureChest?.gameObject.activeSelf==true)add(treasureChest,treasureChest.anchoredPosition.y,2,"treasure-chest");if(treasureChimes?.gameObject.activeSelf==true)add(treasureChimes,treasureChimes.anchoredPosition.y,2,"windchimes");if(treasureTeacher?.gameObject.activeSelf==true)add(treasureTeacher,treasureTeacher.anchoredPosition.y,3,"treasure-calypso");if(treasureEnding?.gameObject.activeSelf==true)add(treasureEnding,treasureEnding.anchoredPosition.y,3,"treasure-toys");}
  private void ResetTreasure(){treasureHud=treasureBelt=treasureOpening=treasureChest=treasureChimes=treasureEnding=treasureTeacher=null;treasureTeacherPoint=Vector2.zero;treasureClockRendered=0;treasurePresentationClock.Reset();treasureTeacherLocomotion.Reset();treasureCovers.Clear();treasureFinds.Clear();treasureMounds.Clear();treasurePieces.Clear();treasureActions.Clear();treasureActionIcons.Clear();treasureActionLabels.Clear();treasureFriends.Clear();treasureNpcPoints.Clear();treasureMotion.Clear();treasureMapMarks.Clear();treasureMap=null;treasureApproach="";treasureSending=false;treasureSpoken=treasureRound=treasureFrame=-1;foreach(var c in treasureAudio)if(c!=null)Resources.UnloadAsset(c);treasureAudio.Clear();}
 }
}
